/// <summary>
/// Helper class for processing transfer orders from Campbells warehouses.
/// Implements auto-shipment and auto-receipt logic for CSD and non-CSD transfer orders.
/// </summary>
public class METCampbellTransferOrderProcessHelper
{
}

Method.Source:
/// <summary>
/// Processes a transfer order picklist for Campbells warehouse logic.
/// If the picklist is for a TO and the "From warehouse" is Campbells, applies special processing:
/// - For CSD TOs: auto ship, auto receive, and consume stock to related SO.
/// - For non-CSD TOs: auto ship only.
/// </summary>
/// <param name="_inventTransferTable">The transfer order table record.</param>
/// <param name="_pickListId">The pick list ID being processed.</param>
public static void processCampbellsTransferOrder(InventTransferTable _inventTransferTable, str _pickListId)
{
    // 1. Check if picklist is for a TO
    if (!_inventTransferTable)
    {
        return;
    }

    // 2. Check if "From warehouse" is Campbells
    if (!METCampbellTransferOrderProcessHelper::isCampbellsWarehouse(_inventTransferTable.InventLocationIdFrom))
    {
        return;
    }

    // 3. Process based on TransferType
