    //{
    //    // CSD: Auto ship, auto receive, and consume to related SO
    //    METCampbellTransferOrderProcessHelper::autoShipTransferOrder(_inventTransferTable, _pickListId);
    //    METCampbellTransferOrderProcessHelper::autoReceiveTransferOrder(_inventTransferTable);
    //    METCampbellTransferOrderProcessHelper::consumeToRelatedSalesOrder(_inventTransferTable);
    //}
    //else
    //{
    //    // Non-CSD: Auto ship only
    //    //autoShipTransferOrder(_inventTransferTable, _pickListId);
    //}
}

/// <summary>
/// Determines if the given warehouse is a Campbells warehouse.
/// </summary>
/// <param name="_inventLocationId">Warehouse ID to check.</param>
/// <returns>True if Campbells warehouse, otherwise false.</returns>
private static boolean isCampbellsWarehouse(InventLocationId _inventLocationId)
{
    InventLocation inventLocation = InventLocation::find(_inventLocationId);
    // Replace with actual Campbells warehouse criteria from the Appendix
    return inventLocation.METWHSubEntity == WHSParameters::find().METCampbellSubEntityIndustryKey;
}

